#include "cpu_adam.h"

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m)
{
    using namespace pybind11::literals;
    m.def("adam_update", &ds_adam_step, "DeepSpeed CPU Adam update (C++)");
    m.def("adam_update_scaled",
          &ds_adam_step_scaled,
          "DeepSpeed CPU Adam update with every gradient multiplied by grad_scale first (C++)");
    m.def("adam_update_scaled_copy",
          &ds_adam_step_scaled_copy,
          "adam_update_scaled that also writes the updated parameters in bfloat16 to params_copy "
          "(C++)");
    m.def("adam_block_numel",
          &ds_adam_block_numel,
          "pieces starting at multiples of this element count are updated exactly as one call on "
          "the whole tensor");
    m.def("adam_copy_supported",
          &ds_adam_copy_supported,
          "whether adam_update_scaled_copy is available in this build (C++)");
    m.def("adam_grad_scale_supported",
          &ds_adam_grad_scale_supported,
          "whether adam_update_scaled is available in this build (C++)");
    m.def("adam_rollback", &ds_adam_rollback, "DeepSpeed CPU Adam rollback (C++)");
    m.def("create_adam", &create_adam_optimizer, "DeepSpeed CPU Adam (C++)");
    m.def("destroy_adam", &destroy_adam_optimizer, "DeepSpeed CPU Adam destroy (C++)");

    // ZenFlowAdam: the native CPU Adam backing ZenFlow's overlapped optimizer step. create /
    // register_group / destroy set up the handle-indexed pinned pool (used by the worker process).
    m.def("zenflow_adam_create", &zenflow_adam_create, "ZenFlowAdam create (C++)");
    m.def("zenflow_adam_register_group",
          &zenflow_adam_register_group,
          "ZenFlowAdam register a parameter group (C++)");
    m.def("zenflow_adam_destroy",
          &zenflow_adam_destroy,
          "ZenFlowAdam destroy (C++)",
          pybind11::call_guard<pybind11::gil_scoped_release>());

#if defined(__linux__)
    // The optimizer runs in a separate process, coordinated through a shared-memory semaphore
    // control block. submit/wait/run_worker release the GIL so the optimizer process overlaps
    // the Python training thread.
    m.def(
        "zenflow_adam_ctrl_size", &zenflow_adam_ctrl_size, "ZenFlowAdam control block size (C++)");
    m.def("zenflow_adam_ctrl_init", &zenflow_adam_ctrl_init, "ZenFlowAdam control init (C++)");
    m.def("zenflow_adam_run_worker",
          &zenflow_adam_run_worker,
          "ZenFlowAdam optimizer-process worker loop (C++)",
          pybind11::call_guard<pybind11::gil_scoped_release>());
    m.def("zenflow_adam_submit",
          &zenflow_adam_submit,
          "ZenFlowAdam submit an overlapped step (C++)",
          pybind11::call_guard<pybind11::gil_scoped_release>());
    m.def("zenflow_adam_wait",
          &zenflow_adam_wait,
          "ZenFlowAdam wait for a submitted step (C++)",
          pybind11::call_guard<pybind11::gil_scoped_release>());
    m.def("zenflow_adam_ctrl_exit",
          &zenflow_adam_ctrl_exit,
          "ZenFlowAdam cross-process exit (C++)",
          pybind11::call_guard<pybind11::gil_scoped_release>());
#endif
}

}

bool ds_adam_copy_supported()
{
    // The vectorized loop needs a bfloat16 store (AVX512 or NEON); the SVE and RVV kernels do not
    // write the copy.
#if defined(__AVX512__) or defined(__NEON__)
    return true;
#elif defined(__AVX256__)
    return false;
#elif defined(__SVE__) && defined(__ARM_FEATURE_SVE)
    return false;
#elif defined(__RVV__) && defined(__riscv_v_intrinsic) && __riscv_v_intrinsic >= 12000
    return false;
#else
    return true;
#endif
}

bool ds_adam_grad_scale_supported()
{
    // Step_RVV does not apply _grad_scale.
#if defined(__RVV__) && defined(__riscv_v_intrinsic) && __riscv_v_intrinsic >= 12000
    return false;
#else
    return true;
#endif
}

size_t ds_adam_block_numel()
{
    // Step_8 updates the first ROUND_DOWN(n, SIMD_WIDTH * 8) elements with the widest vector loop
    // and the rest with narrower loops and finally scalar code, whose float rounding can differ
    // (fused multiply-add or not). A call on a piece that starts at a multiple of this count sends
    // every element through the same code as one call on the whole tensor.
#if defined(__AVX512__) or defined(__AVX256__) or defined(__NEON__)
    return SIMD_WIDTH * 8;
#else
    return 1;
#endif
}

